shader.agsl:
uniform float2 iResolution;
uniform float iTime;
half4 main(float2 fragCoord) {
  float2 uv = fragCoord / iResolution.y;
  float t = iTime * 0.8;
  float v = sin(uv.x * 6.0 + t);
  v += sin(uv.y * 5.0 - t * 1.3);
  v += sin((uv.x + uv.y) * 4.0 + t * 0.7);
  v += sin(length(uv - float2(0.9 + 0.5 * sin(t * 0.5), 0.5)) * 9.0 - t);
  float3 c = 0.5 + 0.5 * cos(3.14159 * v * 0.5 + float3(0.0, 2.1, 4.2));
  return half4(half3(c), 1.0);
}
